use super::*;
#[test]
fn original_scalar_leaf_native_zero_copy_close_keeps_original_value_until_admitted_metadata(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["grant"];let n=|key:&str|p[key].as_u64().unwrap()as usize;let grant=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};for row in law["values"].as_array().unwrap(){let value=row.as_i64().unwrap();let mut cursor=Leaf{value:Some(value)};assert_eq!(cursor.next_work_byte_demand().unwrap(),0);for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,(born,released))=crate::value::observe_retirement_allocations(||cursor.close_step(denied));assert!(matches!(result,RetirementStep::BudgetExhausted));assert_eq!((born,released),(0,0));assert_eq!(cursor.value,Some(value));assert!(!cursor.terminal_is_empty())}let(result,(born,released))=crate::value::observe_retirement_allocations(||cursor.close_step(grant));assert!(matches!(result,RetirementStep::Complete));assert_eq!((born,released),(0,0));assert!(cursor.terminal_is_empty());assert_eq!(cursor.value,None);let(_,(born,released))=crate::value::observe_retirement_allocations(||drop(cursor));assert_eq!((born,released),(0,0));}eprintln!("[DEBUG] Original scalar leaves preserve actual values on item/depth denial; original fixed copy0 removes only metadata with heap0 and terminalDrop0");
}
